PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE recordatorios (
  id TEXT PRIMARY KEY,
  suscripcion_push TEXT NOT NULL,   -- JSON.stringify() de la PushSubscription completa
  fecha_hora_utc INTEGER NOT NULL,  -- timestamp Unix (segundos) de cuándo debe dispararse
  titulo TEXT NOT NULL,
  cuerpo TEXT,
  enviado INTEGER DEFAULT 0
);
CREATE TABLE eventos_activos (
  id TEXT PRIMARY KEY,              -- mismo id que el evento de Agenda (evento.id)
  suscripcion_endpoint TEXT NOT NULL, -- endpoint de la PushSubscription — ver comentario en index.js sobre por qué esto y no la suscripción completa
  suscripcion_push TEXT NOT NULL,   -- JSON.stringify() de la PushSubscription completa, para poder mandar el push del resumen
  fecha_evento TEXT NOT NULL        -- "YYYY-MM-DD", fecha LOCAL del evento tal cual la manda el cliente (no timestamp — el resumen compara fecha civil, no hora exacta)
);
CREATE TABLE resumen_config (
  suscripcion_endpoint TEXT PRIMARY KEY,
  suscripcion_push TEXT NOT NULL,   -- JSON.stringify() de la PushSubscription completa
  hora_local TEXT NOT NULL,         -- "HH:MM" elegida en Ajustes, en la hora LOCAL del usuario
  -- Minutos que hay que RESTAR a UTC para llegar a la hora local del
  -- usuario (mismo signo/convención que Date.prototype.getTimezoneOffset()
  -- en JS: Costa Rica UTC-6 = 360). Se manda desde el cliente junto con
  -- hora_local (ver notificaciones-push.js) porque el Worker no tiene
  -- forma propia de saber en qué zona horaria está cada usuario — sin
  -- esto, "avisame a las 8pm" no tendría con qué compararse contra la
  -- hora UTC en la que corre el cron. Se recalcula en el cron cada vez
  -- (no se guarda ya convertido a UTC) para no tener que reescribir la
  -- fila entera si el usuario cruza un cambio de horario de verano.
  offset_minutos_utc INTEGER NOT NULL DEFAULT 0,
  activo INTEGER DEFAULT 1,
  -- Última fecha (YYYY-MM-DD, en la zona horaria de ese usuario) en la que
  -- ya se mandó el resumen — evita mandarlo 2 veces si el cron corre más
  -- de una vez dentro del mismo minuto/hora exacta, o si por lo que sea el
  -- cron de ese minuto se reintenta.
  ultimo_envio_fecha TEXT
);
CREATE TABLE bandeja_pendiente (
  id TEXT PRIMARY KEY,
  id_bandeja TEXT NOT NULL,
  texto TEXT,
  audio_base64 TEXT,
  creado_en INTEGER NOT NULL  -- timestamp Unix (segundos), misma convención que fecha_hora_utc de arriba
);
CREATE TABLE competencias (
  id TEXT PRIMARY KEY,
  nombre TEXT NOT NULL,
  token_creador TEXT NOT NULL,        -- generado server-side al crear, se devuelve UNA vez en la respuesta de POST /competencias; el cliente lo guarda en localStorage y es lo único que autoriza DELETE /competencias/:id
  offset_minutos_utc INTEGER NOT NULL DEFAULT 0,  -- huso horario LOCAL del creador al momento de crear la competencia; ancla el corte semanal de TODA la competencia
  ultimo_cierre_en INTEGER NOT NULL,  -- epoch ms del último lunes 00:00 (hora local del creador) ya procesado por el cron — evita reprocesar el mismo cierre 2 veces si scheduled() corre más de una vez en la ventana
  creado_en INTEGER NOT NULL
, estado TEXT NOT NULL DEFAULT 'activa');
CREATE TABLE participantes (
  id TEXT PRIMARY KEY,
  competencia_id TEXT NOT NULL,
  apodo TEXT NOT NULL,
  identificador_usuario TEXT NOT NULL,  -- estado.datos.perfil.correo del cliente, tal cual
  horas_semana_actual REAL NOT NULL DEFAULT 0,
  offset_minutos_utc INTEGER NOT NULL DEFAULT 0, token_creador_pendiente TEXT, horas_totales_historicas REAL NOT NULL DEFAULT 0,  -- informativo, ver nota de arriba — el cron NO lo usa
  UNIQUE (competencia_id, identificador_usuario)  -- una persona no puede unirse 2 veces a la misma competencia
);
CREATE TABLE historial_ganadores (
  id TEXT PRIMARY KEY,
  competencia_id TEXT NOT NULL,
  participante_id TEXT NOT NULL,
  apodo TEXT NOT NULL,   -- se copia tal cual estaba al momento del cierre, no es un FK vivo — si el participante se sale o cambia de apodo después, el historial no se altera
  horas REAL NOT NULL,
  semana_cerrada_en INTEGER NOT NULL  -- epoch ms del lunes 00:00 local-del-creador que cerró esa semana (mismo valor que quedó en competencias.ultimo_cierre_en en ese momento)
);
CREATE INDEX idx_recordatorios_pendientes
  ON recordatorios (enviado, fecha_hora_utc);
CREATE INDEX idx_eventos_activos_fecha
  ON eventos_activos (suscripcion_endpoint, fecha_evento);
CREATE INDEX idx_bandeja_pendiente_buzon
  ON bandeja_pendiente (id_bandeja, creado_en);
CREATE INDEX idx_participantes_competencia
  ON participantes (competencia_id);
CREATE INDEX idx_historial_competencia
  ON historial_ganadores (competencia_id, semana_cerrada_en);
